const dv = (d, p) => { let s = 0; for (let i = 0; i < d.length; i++) { s += d[i] * (p - i); } const r = s % 11; return r < 2 ? 0 : 11 - r; };
let base;
do { base = Array.from({length: 9}, () => Math.floor(Math.random() * 10)); } while (new Set(base).size === 1);
const d1 = dv(base, 10);
const d2 = dv(base.concat(d1), 11);
const n = base.concat(d1, d2).join('');
pm.collectionVariables.set('cpfA', n.slice(0,3) + '.' + n.slice(3,6) + '.' + n.slice(6,9) + '-' + n.slice(9));

pm.test("Status 201", () => pm.response.to.have.status(201));

const dvConta = (n) => { let s = 0, p = 2; for (const c of String(n).split('').reverse()) { s += Number(c) * p; p = p === 9 ? 2 : p + 1; } const r = s % 11; return r < 2 ? 0 : 11 - r; };

const r = pm.response.json();
pm.test("Resposta traz numero, digito, documento, saldo e criadaEm", () => {
  pm.expect(r).to.include.keys("numero", "digito", "documento", "saldo", "criadaEm");
});
pm.test("Saldo inicial é zero", () => pm.expect(Number(r.saldo)).to.eql(0));
pm.test("Documento salvo sem máscara", () => {
  pm.expect(r.documento).to.eql(pm.collectionVariables.get('cpfA').replace(/[^0-9A-Za-z]/g, ''));
});
pm.test("Dígito verificador confere (módulo 11)", () => pm.expect(r.digito).to.eql(dvConta(r.numero)));
pm.test("Dígito entre 0 e 9", () => pm.expect(r.digito).to.be.within(0, 9));
pm.collectionVariables.set('numeroA', r.numero);
pm.collectionVariables.set('digitoA', r.digito);

pm.test("Status 200", () => pm.response.to.have.status(200));
const r = pm.response.json();
pm.test("Nenhuma movimentação no período", () => {
  pm.expect(r.movimentacoes).to.be.an("array").that.is.empty;
  pm.expect(r.totalMovimentacoes).to.eql(0);
});
pm.test("Saldo total continua sendo o saldo atual (350)", () => pm.expect(Number(r.saldoTotal)).to.eql(350));
pm.test("Período devolvido é o solicitado", () => {
  pm.expect(r.inicio).to.eql("2020-01-01");
  pm.expect(r.fim).to.eql("2020-01-31");
});

pm.test("Status 200", () => pm.response.to.have.status(200));
const r = pm.response.json();
pm.test("Tamanho limitado a 100", () => {
  pm.expect(r.tamanho).to.be.at.most(100);
  pm.expect(r.conteudo.length).to.be.at.most(100);
});
